	if (mapping == null) {
		return output;
	}

	// Get the field names from the mapping
	List<String> fields = mapping.keySet()
		.stream()
		.map(String::valueOf)
		.collect(Collectors.toList());

	// If there are no fields in the mapping, return an empty map
	if (fields.isEmpty()) {
		return output;
	}

	// Iterate over all fields in the mapping and check if they exist in the input mappings
	for (String field : fields) {
		if (!mappings.containsField(field)) {
			// If the field does not exist in the input mappings, add it to the output
