private void removeSubtree(Category currentRoot) {
   // Recursively traverse the subtree and remove all of its nodes
   Queue<Category> toRemove = new LinkedList<>();
   Queue<Category> toVisit = new LinkedList<>();
   toVisit.add(currentRoot);

   while (!toVisit.isEmpty()) {
      Category current = toVisit.remove();
      toRemove.add(current);

      // Recursively traverse the children of the current node
      for (Category child : current.getChildren()) {
         toVisit.add(child);
      }
   }

