                    PopInt();
                    break;
                case "J":
                    PopLong();
                    break;
                case "F":
                    PopFloat();
                    break;
                case "D":
                    PopDouble();
                    break;
                default:
                    throw new ArgumentException("Invalid descriptor: " + descriptor);
