private List<Integer> computeUpperBounds(List<K> keys) {
    List<Integer> upperBounds = new ArrayList<>();
    for (K key : keys) {
        int currentUpperBound = key.hashCode();
        int lowerBound = 0;
        for (int i = 0; i < keys.size(); i++) {
            if (keys.get(i).equals(key)) {
                lowerBound = i;
                break;
            }
        }
        upperBounds.add(currentUpperBound - lowerBound + 1);
    }
    return upperBounds;
}
